import base64
import json
import logging
import time
import websocket

from .keys.mapper import KeyMapper


class SamsungTV():

    _URL_FORMAT = 'ws://{host}:{port}/api/v2/channels/samsung.remote.control?name={name}'

    _KEY_INTERVAL = 1.5

    def __init__(self, host, port=8001, name='SamsungTvRemote'):
        self.connection = websocket.create_connection(
            self._URL_FORMAT.format(**{
                'host': host, 
                'port': port, 
                'name': self._serialize_string(name)
            })
        )

        response = json.loads(self.connection.recv())
        if response['event'] != 'ms.channel.connect':
            self.close()
            raise Exception(response)

        self._mapper = KeyMapper(self.send_key)

    def __exit__(self, type, value, traceback):
        self.close()

    def _serialize_string(self, string):
        if isinstance(string, str):
            string = str.encode(string)
        return base64.b64encode(string).decode('utf-8')

    def close(self):
        if self.connection:
            self.connection.close()
            self.connection = None
            logging.debug('Connection closed.')

    def send_key(self, key, repeat=1):
        for n in range(repeat):
            payload = json.dumps({
                'method': 'ms.remote.control',
                'params': {
                    'Cmd': 'Click',
                    'DataOfCmd': key,
                    'Option': 'false',
                    'TypeOfRemote': 'SendRemoteKey'
                }
            })

            logging.info('Sending key %s', key)
            self.connection.send(payload)
            time.sleep(self._KEY_INTERVAL)

    # power
    def power(self):
        self._mapper.power()

    # menu
    def home(self):
        self._mapper.home()

    def menu(self):
        self._mapper.menu()

    def source(self):
        self._mapper.source()

    def guide(self):
        self._mapper.guide()

    def tools(self):
        self._mapper.tools()

    def info(self):
        self._mapper.info()

    # navigation
    def up(self, count=1):
        self._mapper.up(count)

    def down(self, count=1):
        self._mapper.down(count)

    def left(self, count=1):
        self._mapper.left(count)

    def right(self, count=1):
        self._mapper.right(count)

    def enter(self, count=1):
        self._mapper.enter(count)

    def back(self, count=1):
        self._mapper.back(count)

    # channel
    def channel_list(self):
        self._mapper.channel_list()

    def channel(self, ch):
        self._mapper.channel(ch)

    def digit(self, d):
        self._mapper.digit(d)

    def channel_up(self, count=1):
        self._mapper.channel_up(count)

    def channel_down(self, count=1):
        self._mapper.channel_down(count)

    # volume
    def volume_up(self, count=1):
        self._mapper.volume_up(count)

    def volume_down(self, count=1):
        self._mapper.volume_down(count)

    def mute(self):
        self._mapper.mute()

    # extra
    def red(self):
        self._mapper.red()

    def green(self):
        self._mapper.green()

    def yellow(self):
        self._mapper.yellow()

    def blue(self):
        self._mapper.blue()
